```javascript
document.addEventListener('DOMContentLoaded', function() {
  const table = document.querySelector('.table');

  if (!table) {
    console.error('Table not found.');
    return;
  }

  const headers = table.querySelectorAll('th');

  headers.forEach(header => {
    header.addEventListener('click', function() {
      const sortType = this.dataset.sort;
      const columnIndex = Array.from(headers).indexOf(this); // Get the column index

      sortTable(table, columnIndex, sortType);
    });
  });

  function sortTable(table, columnIndex, sortType) {
    const tbody = table.querySelector('tbody');
    const rows = Array.from(tbody.querySelectorAll('tr'));

    rows.sort((a, b) => {
      const cellA = a.querySelectorAll('td')[columnIndex].textContent;
      const cellB = b.querySelectorAll('td')[columnIndex].textContent;

      let comparison = 0;

      switch (sortType) {
        case 'number':
          comparison = parseFloat(cellA) - parseFloat(cellB);
          break;
        case 'date':
          comparison = new Date(cellA) - new Date(cellB);
          break;
        case 'string':
        default:
          comparison = cellA.localeCompare(cellB);
      }

      return comparison;
    });

    // Clear the table body and append the sorted rows
    tbody.innerHTML = '';
    rows.forEach(row => tbody.appendChild(row));
  }
});
```

**Explanation of the JavaScript:**

*   **`DOMContentLoaded`:**  Ensures the script runs after the HTML is fully loaded.
*   **`document.querySelector('.table')`:** Selects the table element.
*   **`headers.forEach(...)`:**  Iterates through each header cell (`<th>`).
*   **`header.addEventListener('click', ...)`:**  Attaches a click event listener to each header.
*   **`sortType = this.dataset.sort`:**  Gets the sorting type from the `data-sort` attribute of the clicked header.
