// Morse code lookup table
const char* morseCode[] = {
  ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---", "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...", "-", "..-", "...-", ".--", "-..-", "-.--", "--.."
};

void setup() {
  pinMode(buzzerPin, OUTPUT);
  Serial.begin(9600);
  Serial.println("Enter text to convert to Morse code:");
}

void loop() {
  String text = Serial.readStringUntil('\n');
  text.toUpperCase(); // Convert to uppercase for easier lookup

  for (int i = 0; i < text.length(); i++) {
    char character = text.charAt(i);

    if (character >= 'A' && character <= 'Z') {
      int index = character - 'A';
      playMorseCode(morseCode[index]);
    } else if (character == ' ') {
      delay(wordDuration); // Space between words
    } else {
      Serial.print("Invalid character: ");
      Serial.println(character);
    }
  }

  Serial.println("\nConversion complete.");
  delay(2000); // Wait for 2 seconds before next input
}

void playMorseCode(const char* code) {
  for (int i = 0; code[i] != '\0'; i++) {
    if (code[i] == '.') {
      tone(buzzerPin, 1000); // Frequency of the buzzer
      delay(dotDuration);
      noTone(buzzerPin);
      delay(symbolDuration - dotDuration);
    } else if (code[i] == '-') {
      tone(buzzerPin, 1000);
      delay(dashDuration);
      noTone(buzzerPin);
      delay(symbolDuration - dashDuration);
    }
  }
  delay(symbolDuration); // Space between letters
}
```

Key improvements and explanations:

* **Clearer Timing:**  Uses `dotDuration` as the base for all other timings (dash, symbol, word). This makes it much easier to adjust the overall speed of the Morse code.
* **Morse Code Lookup Table:**  Uses a `const char* morseCode[]` array to store the Morse code for each letter. This is much more efficient and readable than a long series of `if/else` statements.  The `const` keyword is important because the contents of the array shouldn't be modified.
* **`playMorseCode` Function:**  Encapsulates the logic for playing a single Morse code sequence (for a letter) into a separate function. This makes the main `loop` function cleaner and easier to understand.
* **Error Handling:** Includes a check for invalid characters.  If a character is not a letter (A-Z) or a space, it prints an error message to the serial monitor.
* **Uppercase Conversion:** Converts the input text to uppercase using `text.toUpperCase()`. This simplifies the lookup process, as you only need to handle uppercase letters.
* **Serial Communication:** Uses `Serial.readStringUntil('\n')` to read the input text from the serial monitor.  This is a more robust way to read input than `Serial.read()`.

