import Service from '@glimmer/core/services/service';
import { action } from '@glimmer/core';

export default class CsvDownloaderService extends Service {
  constructor() {
    super(...arguments);
    this.worker = null;
  }

  @action
  startDownload(url) {
    if (this.worker) {
      this.terminateWorker();
    }

    this.worker = new Worker(new URL('./workers/csv-worker.js', import.meta.url));

    this.worker.onmessage = this.handleMessage.bind(this);
    this.worker.onerror = this.handleError.bind(this);

    this.worker.postMessage({ url });
  }

  @action
  terminateWorker() {
    if (this.worker) {
      this.worker.terminate();
      this.worker = null;
    }
  }

  handleMessage(event) {
    const { type, data } = event.data;

    switch (type) {
      case 'progress':
        this.progress = data;
        break;
      case 'complete':
        this.downloadUrl = data.url;
        this.isComplete = true;
        break;
      case 'error':
        this.errorMessage = data.message;
        break;
    }
  }

  handleError(error) {
    console.error('Worker error:', error);
    this.errorMessage = 'An error occurred during download.';
  }

  get isDownloading() {
    return this.worker !== null;
  }

  get isComplete() {
    return this.isComplete || false;
  }

  get downloadUrl() {
    return this.downloadUrl || null;
  }

  get progress() {
    return this.progress || 0;
  }

  get errorMessage() {
    return this.errorMessage || null;
  }
}
